    hero_label: "Portafolio / 2026",
    hero_title: 'Hola, soy <span class="hero-name">Giulia Alvares</span>,',
    hero_subtitle: 'un <em>\u201cno s\u00e9 qu\u00e9\u201d</em> en construcci\u00f3n.',
    hero_description: "Soy una constructora multidisciplinaria navegando negocios, tecnolog\u00eda, investigaci\u00f3n y arte. Creo cosas en la intersecci\u00f3n de ambici\u00f3n, curiosidad y ejecuci\u00f3n.",
